import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Settings, Save, RefreshCw, AlertCircle, CheckCircle,
  Mail, MessageSquare, Smartphone, Bell
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { useApi } from '../hooks/useApi'

interface NotificationPreference {
  id: string
  user_id: number
  team_id?: number
  email_enabled: boolean
  sms_enabled: boolean
  in_app_enabled: boolean
  created_at: string
  updated_at: string
}

interface Team {
  id: number
  name: string
}

interface NotificationSettingsProps {
  userId: number
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function NotificationSettings({ userId }: NotificationSettingsProps) {
  const [preferences, setPreferences] = useState<NotificationPreference[]>([])
  const [teams, setTeams] = useState<Team[]>([])
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  const { execute } = useApi()

  useEffect(() => {
    fetchPreferences()
    fetchTeams()
  }, [])

  const fetchPreferences = async () => {
    setLoading(true)
    try {
      const response = await execute(`http://localhost:8000/api/users/${userId}/notification-preferences`)
      if (response?.preferences) {
        setPreferences(response.preferences)
      }
    } catch (error) {
      console.error('Error fetching notification preferences:', error)
      setMessage({ type: 'error', text: 'Failed to fetch notification preferences' })
    } finally {
      setLoading(false)
    }
  }

  const fetchTeams = async () => {
    try {
      const response = await execute('http://localhost:8000/api/teams')
      if (response?.teams) {
        setTeams(response.teams)
      }
    } catch (error) {
      console.error('Error fetching teams:', error)
    }
  }

  const handlePreferenceChange = (preferenceId: string, field: keyof Pick<NotificationPreference, 'email_enabled' | 'sms_enabled' | 'in_app_enabled'>, value: boolean) => {
    setPreferences(prev =>
      prev.map(pref =>
        pref.id === preferenceId
          ? { ...pref, [field]: value }
          : pref
      )
    )
  }

  const savePreferences = async () => {
    setSaving(true)
    try {
      await execute(`http://localhost:8000/api/users/${userId}/notification-preferences`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences })
      })

      setMessage({ type: 'success', text: 'Notification preferences saved successfully' })
      setTimeout(() => setMessage(null), 3000)
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to save preferences' })
    } finally {
      setSaving(false)
    }
  }

  const getTeamName = (teamId?: number): string => {
    if (!teamId) return 'Global Settings'
    const team = teams.find(t => t.id === teamId)
    return team?.name || `Team ${teamId}`
  }

  const clearMessage = () => {
    setMessage(null)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
        <span className="ml-3 text-gray-500">Loading notification settings...</span>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="p-2 bg-blue-100 rounded-lg">
            <Settings className="h-6 w-6 text-blue-600" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Notification Settings</h2>
            <p className="text-gray-600">Manage your notification preferences for teams and events</p>
          </div>
        </div>
        <Button
          onClick={savePreferences}
          disabled={saving}
          className="flex items-center space-x-2"
        >
          <Save className="h-4 w-4" />
          <span>{saving ? 'Saving...' : 'Save Changes'}</span>
        </Button>
      </div>

      {/* Message Display */}
      <AnimatePresence>
        {message && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`p-4 rounded-lg border ${
              message.type === 'success'
                ? 'bg-green-50 border-green-200 text-green-800'
                : 'bg-red-50 border-red-200 text-red-800'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                {message.type === 'success' ? (
                  <CheckCircle className="h-5 w-5" />
                ) : (
                  <AlertCircle className="h-5 w-5" />
                )}
                <span>{message.text}</span>
              </div>
              <Button variant="ghost" size="sm" onClick={clearMessage}>
                ×
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Notification Preferences */}
      {preferences.length === 0 ? (
        <Card>
          <CardContent className="flex items-center justify-center py-12">
            <div className="text-center">
              <Bell className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">
                No notification preferences found
              </h3>
              <p className="text-gray-500 mb-4">
                Your notification preferences will be created automatically when you join teams.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="space-y-4"
        >
          {preferences.map((preference) => (
            <motion.div key={preference.id} variants={itemVariants}>
              <Card className="hover:shadow-md transition-shadow">
                <CardHeader>
                  <CardTitle className="flex items-center space-x-2">
                    <Bell className="h-5 w-5 text-blue-600" />
                    <span>{getTeamName(preference.team_id)}</span>
                  </CardTitle>
                  <CardDescription>
                    Configure how you want to receive notifications for {getTeamName(preference.team_id).toLowerCase()}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Email Notifications */}
                    <div className="flex items-center justify-between p-4 border rounded-lg">
                      <div className="flex items-center space-x-3">
                        <div className="p-2 bg-blue-100 rounded-lg">
                          <Mail className="h-5 w-5 text-blue-600" />
                        </div>
                        <div>
                          <h4 className="font-medium text-gray-900">Email</h4>
                          <p className="text-sm text-gray-500">Receive email notifications</p>
                        </div>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input
                          type="checkbox"
                          checked={preference.email_enabled}
                          onChange={(e) => handlePreferenceChange(preference.id, 'email_enabled', e.target.checked)}
                          className="sr-only peer"
                        />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                      </label>
                    </div>

                    {/* SMS Notifications */}
                    <div className="flex items-center justify-between p-4 border rounded-lg">
                      <div className="flex items-center space-x-3">
                        <div className="p-2 bg-green-100 rounded-lg">
                          <MessageSquare className="h-5 w-5 text-green-600" />
                        </div>
                        <div>
                          <h4 className="font-medium text-gray-900">SMS</h4>
                          <p className="text-sm text-gray-500">Receive text messages</p>
                        </div>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input
                          type="checkbox"
                          checked={preference.sms_enabled}
                          onChange={(e) => handlePreferenceChange(preference.id, 'sms_enabled', e.target.checked)}
                          className="sr-only peer"
                        />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-green-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-600"></div>
                      </label>
                    </div>

                    {/* In-App Notifications */}
                    <div className="flex items-center justify-between p-4 border rounded-lg">
                      <div className="flex items-center space-x-3">
                        <div className="p-2 bg-purple-100 rounded-lg">
                          <Smartphone className="h-5 w-5 text-purple-600" />
                        </div>
                        <div>
                          <h4 className="font-medium text-gray-900">In-App</h4>
                          <p className="text-sm text-gray-500">Receive in-app notifications</p>
                        </div>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input
                          type="checkbox"
                          checked={preference.in_app_enabled}
                          onChange={(e) => handlePreferenceChange(preference.id, 'in_app_enabled', e.target.checked)}
                          className="sr-only peer"
                        />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                      </label>
                    </div>
                  </div>

                  <div className="mt-4 p-3 bg-gray-50 rounded-lg">
                    <p className="text-sm text-gray-600">
                      Last updated: {new Date(preference.updated_at).toLocaleDateString('en-US', {
                        year: 'numeric',
                        month: 'short',
                        day: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit'
                      })}
                    </p>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </motion.div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Send, Users, Calendar, Eye, RefreshCw, AlertCircle, CheckCircle,
  Mail, MessageSquare, Smartphone, Filter, Search, Clock
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select'
import { useApi } from '../hooks/useApi'
import { ApiEvent } from '../lib/api'

interface NotificationTemplate {
  id: string
  name: string
  type: 'email' | 'sms' | 'push' | 'in_app'
  subject?: string
  body: string
  placeholders: Record<string, string>
  is_active: boolean
}

interface Team {
  id: number
  name: string
}

interface User {
  id: number
  first_name: string
  last_name: string
  email: string
  teams: number[]
}

interface ScheduleChangeNotifierProps {
  onBack?: () => void
}

const deliveryMethodConfig = {
  email: { label: 'Email', icon: Mail, color: 'text-blue-600', bg: 'bg-blue-100' },
  sms: { label: 'SMS', icon: MessageSquare, color: 'text-green-600', bg: 'bg-green-100' },
  push: { label: 'Push', icon: Smartphone, color: 'text-purple-600', bg: 'bg-purple-100' },
  in_app: { label: 'In-App', icon: Calendar, color: 'text-orange-600', bg: 'bg-orange-100' }
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function ScheduleChangeNotifier({ onBack }: ScheduleChangeNotifierProps) {
  const [events, setEvents] = useState<ApiEvent[]>([])
  const [teams, setTeams] = useState<Team[]>([])
  const [users, setUsers] = useState<User[]>([])
  const [templates, setTemplates] = useState<NotificationTemplate[]>([])
  const [loading, setLoading] = useState(false)
  const [sending, setSending] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  // Form states
  const [selectedEvent, setSelectedEvent] = useState<string>('')
  const [recipientType, setRecipientType] = useState<'team' | 'all' | 'custom'>('team')
  const [selectedTeams, setSelectedTeams] = useState<number[]>([])
  const [selectedUsers, setSelectedUsers] = useState<number[]>([])
  const [deliveryMethods, setDeliveryMethods] = useState<string[]>(['email'])
  const [templateId, setTemplateId] = useState<string>('')
  const [customMessage, setCustomMessage] = useState('')
  const [useTemplate, setUseTemplate] = useState(true)
  const [placeholders, setPlaceholders] = useState<Record<string, string>>({})

  // Preview states
  const [showPreview, setShowPreview] = useState(false)
  const [previewContent, setPreviewContent] = useState<{ subject?: string; body: string } | null>(null)

  // Filter states
  const [eventFilter, setEventFilter] = useState('')
  const [filteredEvents, setFilteredEvents] = useState<ApiEvent[]>([])

  const { execute } = useApi()

  useEffect(() => {
    fetchEvents()
    fetchTeams()
    fetchUsers()
    fetchTemplates()
  }, [])

  useEffect(() => {
    filterEvents()
  }, [events, eventFilter])

  const fetchEvents = async () => {
    setLoading(true)
    try {
      const response = await execute('http://localhost:8000/api/events')
      if (response) {
        setEvents(Array.isArray(response) ? response : [])
      }
    } catch (error) {
      console.error('Error fetching events:', error)
      setMessage({ type: 'error', text: 'Failed to fetch events' })
    } finally {
      setLoading(false)
    }
  }

  const fetchTeams = async () => {
    try {
      const response = await execute('http://localhost:8000/api/teams')
      if (response?.teams) {
        setTeams(response.teams)
      }
    } catch (error) {
      console.error('Error fetching teams:', error)
    }
  }

  const fetchUsers = async () => {
    try {
      const response = await execute('http://localhost:8000/api/users')
      if (response?.users) {
        setUsers(response.users)
      }
    } catch (error) {
      console.error('Error fetching users:', error)
    }
  }

  const fetchTemplates = async () => {
    try {
      const response = await execute('http://localhost:8000/api/notification-templates')
      if (response?.templates) {
        const activeTemplates = response.templates.filter((t: NotificationTemplate) => t.is_active)
        setTemplates(activeTemplates)
      }
    } catch (error) {
      console.error('Error fetching templates:', error)
    }
  }

  const filterEvents = () => {
    let filtered = events

    if (eventFilter) {
      const searchLower = eventFilter.toLowerCase()
      filtered = filtered.filter(event =>
        event.name.toLowerCase().includes(searchLower) ||
        (event.description && event.description.toLowerCase().includes(searchLower)) ||
        event.event_type.toLowerCase().includes(searchLower)
      )
    }

    setFilteredEvents(filtered)
  }

  const getEventRecipients = (): User[] => {
    if (recipientType === 'all') {
      return users
    }

    const event = events.find(e => e.id === selectedEvent)
    if (!event) return []

    if (recipientType === 'team') {
      return users.filter(user =>
        user.teams.some(teamId => event.team_ids.includes(teamId)) ||
        selectedTeams.some(teamId => user.teams.includes(teamId))
      )
    }

    if (recipientType === 'custom') {
      return users.filter(user => selectedUsers.includes(user.id))
    }

    return []
  }

  const generatePreview = () => {
    const event = events.find(e => e.id === selectedEvent)
    if (!event) {
      setMessage({ type: 'error', text: 'Please select an event first' })
      return
    }

    let messageBody = ''
    let messageSubject = ''

    if (useTemplate && templateId) {
      const template = templates.find(t => t.id === templateId)
      if (template) {
        messageBody = template.body
        messageSubject = template.subject || ''
      }
    } else {
      messageBody = customMessage
    }

    // Substitute placeholders
    const substitutePlaceholders = (text: string): string => {
      let result = text

      // Built-in placeholders
      const builtInPlaceholders = {
        '{event_name}': event.name,
        '{event_type}': event.event_type,
        '{event_date}': new Date(event.start_time).toLocaleDateString(),
        '{event_time}': new Date(event.start_time).toLocaleTimeString(),
        '{venue_name}': event.venue?.name || 'TBD',
        '{current_date}': new Date().toLocaleDateString(),
        '{current_time}': new Date().toLocaleTimeString()
      }

      // Apply built-in placeholders
      Object.entries(builtInPlaceholders).forEach(([placeholder, value]) => {
        result = result.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value)
      })

      // Apply custom placeholders
      Object.entries(placeholders).forEach(([key, value]) => {
        const placeholder = `{${key}}`
        result = result.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value)
      })

      return result
    }

    const processedSubject = messageSubject ? substitutePlaceholders(messageSubject) : undefined
    const processedBody = substitutePlaceholders(messageBody)

    setPreviewContent({
      subject: processedSubject,
      body: processedBody
    })

    setShowPreview(true)
  }

  const sendNotifications = async () => {
    if (!selectedEvent) {
      setMessage({ type: 'error', text: 'Please select an event' })
      return
    }

    if (deliveryMethods.length === 0) {
      setMessage({ type: 'error', text: 'Please select at least one delivery method' })
      return
    }

    if (useTemplate && !templateId) {
      setMessage({ type: 'error', text: 'Please select a template' })
      return
    }

    if (!useTemplate && !customMessage.trim()) {
      setMessage({ type: 'error', text: 'Please enter a custom message' })
      return
    }

    const recipients = getEventRecipients()
    if (recipients.length === 0) {
      setMessage({ type: 'error', text: 'No recipients found for the selected criteria' })
      return
    }

    setSending(true)
    try {
      await execute('http://localhost:8000/api/schedule-communication/send-notification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          event_id: selectedEvent,
          recipient_type: recipientType,
          selected_teams: selectedTeams,
          selected_users: selectedUsers,
          delivery_methods: deliveryMethods,
          template_id: useTemplate ? templateId : undefined,
          custom_message: useTemplate ? undefined : customMessage,
          placeholders
        })
      })

      setMessage({
        type: 'success',
        text: `Notifications sent successfully to ${recipients.length} recipient${recipients.length !== 1 ? 's' : ''}`
      })

      // Reset form
      setSelectedEvent('')
      setSelectedTeams([])
      setSelectedUsers([])
      setTemplateId('')
      setCustomMessage('')
      setPlaceholders({})
      setTimeout(() => setMessage(null), 5000)
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to send notifications' })
    } finally {
      setSending(false)
    }
  }

  const clearMessage = () => {
    setMessage(null)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="p-2 bg-blue-100 rounded-lg">
            <Send className="h-6 w-6 text-blue-600" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Schedule Change Notifications</h2>
            <p className="text-gray-600">Send notifications about schedule changes to team members</p>
          </div>
        </div>
      </div>

      {/* Message Display */}
      <AnimatePresence>
        {message && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`p-4 rounded-lg border ${
              message.type === 'success'
                ? 'bg-green-50 border-green-200 text-green-800'
                : 'bg-red-50 border-red-200 text-red-800'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                {message.type === 'success' ? (
                  <CheckCircle className="h-5 w-5" />
                ) : (
                  <AlertCircle className="h-5 w-5" />
                )}
                <span>{message.text}</span>
              </div>
              <Button variant="ghost" size="sm" onClick={clearMessage}>
                ×
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Event Selection */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <Calendar className="h-5 w-5" />
              <span>Select Event</span>
            </CardTitle>
            <CardDescription>Choose the event you want to send notifications about</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
              <Input
                placeholder="Search events..."
                value={eventFilter}
                onChange={(e) => setEventFilter(e.target.value)}
                className="pl-10"
              />
            </div>

            {loading ? (
              <div className="flex items-center justify-center py-8">
                <RefreshCw className="h-6 w-6 animate-spin text-gray-400" />
                <span className="ml-2 text-gray-500">Loading events...</span>
              </div>
            ) : (
              <div className="max-h-64 overflow-y-auto space-y-2">
                {filteredEvents.map((event) => (
                  <div
                    key={event.id}
                    className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                      selectedEvent === event.id
                        ? 'border-blue-500 bg-blue-50'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                    onClick={() => setSelectedEvent(event.id)}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-medium text-gray-900">{event.name}</h4>
                        <p className="text-sm text-gray-500">
                          {event.event_type} • {new Date(event.start_time).toLocaleDateString()} • {event.venue?.name || 'TBD'}
                        </p>
                      </div>
                      <div className={`px-2 py-1 rounded-full text-xs font-medium ${
                        event.event_type === 'Game' ? 'bg-green-100 text-green-800' :
                        event.event_type === 'Practice' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {event.event_type}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Recipient Configuration */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <Users className="h-5 w-5" />
              <span>Recipients</span>
            </CardTitle>
            <CardDescription>Configure who should receive the notification</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Recipient Type</label>
              <Select value={recipientType} onValueChange={(value: 'team' | 'all' | 'custom') => setRecipientType(value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="team">Event Teams</SelectItem>
                  <SelectItem value="all">All Users</SelectItem>
                  <SelectItem value="custom">Custom Selection</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {recipientType === 'team' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Additional Teams</label>
                <Select value="" onValueChange={(value) => {
                  const teamId = parseInt(value)
                  if (!selectedTeams.includes(teamId)) {
                    setSelectedTeams([...selectedTeams, teamId])
                  }
                }}>
                  <SelectTrigger>
                    <SelectValue placeholder="Add teams..." />
                  </SelectTrigger>
                  <SelectContent>
                    {teams.map((team) => (
                      <SelectItem key={team.id} value={team.id.toString()}>
                        {team.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {selectedTeams.length > 0 && (
                  <div className="mt-2 flex flex-wrap gap-2">
                    {selectedTeams.map((teamId) => {
                      const team = teams.find(t => t.id === teamId)
                      return (
                        <span key={teamId} className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                          {team?.name}
                          <button
                            onClick={() => setSelectedTeams(selectedTeams.filter(id => id !== teamId))}
                            className="ml-1 text-blue-600 hover:text-blue-800"
                          >
                            ×
                          </button>
                        </span>
                      )
                    })}
                  </div>
                )}
              </div>
            )}

            {recipientType === 'custom' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Select Users</label>
                <Select value="" onValueChange={(value) => {
                  const userId = parseInt(value)
                  if (!selectedUsers.includes(userId)) {
                    setSelectedUsers([...selectedUsers, userId])
                  }
                }}>
                  <SelectTrigger>
                    <SelectValue placeholder="Add users..." />
                  </SelectTrigger>
                  <SelectContent>
                    {users.map((user) => (
                      <SelectItem key={user.id} value={user.id.toString()}>
                        {user.first_name} {user.last_name} ({user.email})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {selectedUsers.length > 0 && (
                  <div className="mt-2 flex flex-wrap gap-2">
                    {selectedUsers.map((userId) => {
                      const user = users.find(u => u.id === userId)
                      return (
                        <span key={userId} className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                          {user?.first_name} {user?.last_name}
                          <button
                            onClick={() => setSelectedUsers(selectedUsers.filter(id => id !== userId))}
                            className="ml-1 text-green-600 hover:text-green-800"
                          >
                            ×
                          </button>
                        </span>
                      )
                    })}
                  </div>
                )}
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Delivery Methods</label>
              <div className="space-y-2">
                {Object.entries(deliveryMethodConfig).map(([method, config]) => {
                  const Icon = config.icon
                  return (
                    <label key={method} className="flex items-center space-x-2">
                      <input
                        type="checkbox"
                        checked={deliveryMethods.includes(method)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setDeliveryMethods([...deliveryMethods, method])
                          } else {
                            setDeliveryMethods(deliveryMethods.filter(m => m !== method))
                          }
                        }}
                        className="rounded border-gray-300"
                      />
                      <div className={`p-1 rounded ${config.bg}`}>
                        <Icon className={`h-4 w-4 ${config.color}`} />
                      </div>
                      <span className="text-sm font-medium">{config.label}</span>
                    </label>
                  )
                })}
              </div>
            </div>

            <div className="text-sm text-gray-600">
              Recipients: {getEventRecipients().length}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Message Configuration */}
      <Card>
        <CardHeader>
          <CardTitle>Message Configuration</CardTitle>
          <CardDescription>Configure the notification message content</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center space-x-4">
            <label className="flex items-center space-x-2">
              <input
                type="radio"
                checked={useTemplate}
                onChange={() => setUseTemplate(true)}
                className="text-blue-600"
              />
              <span>Use Template</span>
            </label>
            <label className="flex items-center space-x-2">
              <input
                type="radio"
                checked={!useTemplate}
                onChange={() => setUseTemplate(false)}
                className="text-blue-600"
              />
              <span>Custom Message</span>
            </label>
          </div>

          {useTemplate ? (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Select Template</label>
                <Select value={templateId} onValueChange={setTemplateId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Choose a template..." />
                  </SelectTrigger>
                  <SelectContent>
                    {templates.map((template) => (
                      <SelectItem key={template.id} value={template.id}>
                        {template.name} ({template.type})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {templateId && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Custom Placeholders</label>
                  <div className="grid grid-cols-2 gap-4">
                    <Input
                      placeholder="Placeholder key"
                      value=""
                      onChange={() => {}}
                    />
                    <Input
                      placeholder="Placeholder value"
                      value=""
                      onChange={() => {}}
                    />
                  </div>
                  <p className="text-sm text-gray-500 mt-1">
                    Available: {'{event_name}'}, {'{event_type}'}, {'{event_date}'}, {'{event_time}'}, {'{venue_name}'}
                  </p>
                </div>
              )}
            </div>
          ) : (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Custom Message</label>
              <textarea
                value={customMessage}
                onChange={(e) => setCustomMessage(e.target.value)}
                placeholder="Enter your custom message. Use {placeholders} for dynamic content."
                rows={6}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <p className="text-sm text-gray-500 mt-1">
                Available: {'{event_name}'}, {'{event_type}'}, {'{event_date}'}, {'{event_time}'}, {'{venue_name}'}
              </p>
            </div>
          )}

          <div className="flex space-x-3">
            <Button
              variant="outline"
              onClick={generatePreview}
              disabled={!selectedEvent || (useTemplate && !templateId) || (!useTemplate && !customMessage.trim())}
              className="flex items-center space-x-2"
            >
              <Eye className="h-4 w-4" />
              <span>Preview</span>
            </Button>

            <Button
              onClick={sendNotifications}
              disabled={sending || !selectedEvent || (useTemplate && !templateId) || (!useTemplate && !customMessage.trim())}
              className="flex items-center space-x-2"
            >
              <Send className="h-4 w-4" />
              <span>{sending ? 'Sending...' : 'Send Notifications'}</span>
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Preview Modal */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Message Preview</DialogTitle>
            <DialogDescription>
              Preview of the notification message that will be sent
            </DialogDescription>
          </DialogHeader>

          {previewContent && (
            <div className="space-y-4">
              {previewContent.subject && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Subject</label>
                  <div className="p-3 bg-gray-50 rounded-lg border">
                    <p className="text-sm">{previewContent.subject}</p>
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Message Body</label>
                <div className="p-3 bg-gray-50 rounded-lg border">
                  <p className="text-sm whitespace-pre-wrap">{previewContent.body}</p>
                </div>
              </div>

              <div className="p-3 bg-blue-50 rounded-lg border border-blue-200">
                <p className="text-sm text-blue-800">
                  <Clock className="inline h-4 w-4 mr-1" />
                  This will be sent to {getEventRecipients().length} recipient{getEventRecipients().length !== 1 ? 's' : ''} via {deliveryMethods.join(', ')}
                </p>
              </div>
            </div>
          )}

          <div className="flex justify-end space-x-3">
            <Button variant="outline" onClick={() => setShowPreview(false)}>
              Close Preview
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  History, Filter, Search, RefreshCw, Eye, Download, Calendar,
  Mail, MessageSquare, Smartphone, Monitor, CheckCircle, XCircle,
  Clock, AlertTriangle, ChevronLeft, ChevronRight, ArrowUpDown
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select'
import { useApi } from '../hooks/useApi'

interface SentNotification {
  id: string
  event_id: string
  event_name: string
  recipient_user_id: number
  recipient_name: string
  recipient_email: string
  delivery_method: 'email' | 'sms' | 'push' | 'in_app'
  template_id?: string
  template_name?: string
  subject?: string
  body: string
  status: 'pending' | 'sent' | 'delivered' | 'failed' | 'bounced'
  sent_at: string
  delivered_at?: string
  error_message?: string
  created_at: string
}

interface NotificationFilters {
  event_id?: string
  recipient_user_id?: number
  delivery_method?: string
  status?: string
  start_date?: string
  end_date?: string
  search?: string
}

interface PaginationInfo {
  page: number
  per_page: number
  total: number
  total_pages: number
}

const statusConfig = {
  pending: { label: 'Pending', icon: Clock, color: 'text-yellow-600', bg: 'bg-yellow-100' },
  sent: { label: 'Sent', icon: CheckCircle, color: 'text-blue-600', bg: 'bg-blue-100' },
  delivered: { label: 'Delivered', icon: CheckCircle, color: 'text-green-600', bg: 'bg-green-100' },
  failed: { label: 'Failed', icon: XCircle, color: 'text-red-600', bg: 'bg-red-100' },
  bounced: { label: 'Bounced', icon: AlertTriangle, color: 'text-orange-600', bg: 'bg-orange-100' }
}

const deliveryMethodConfig = {
  email: { label: 'Email', icon: Mail, color: 'text-blue-600', bg: 'bg-blue-100' },
  sms: { label: 'SMS', icon: MessageSquare, color: 'text-green-600', bg: 'bg-green-100' },
  push: { label: 'Push', icon: Smartphone, color: 'text-purple-600', bg: 'bg-purple-100' },
  in_app: { label: 'In-App', icon: Monitor, color: 'text-orange-600', bg: 'bg-orange-100' }
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function NotificationLogView() {
  const [notifications, setNotifications] = useState<SentNotification[]>([])
  const [events, setEvents] = useState<{ id: string; name: string }[]>([])
  const [users, setUsers] = useState<{ id: number; name: string; email: string }[]>([])
  const [loading, setLoading] = useState(false)
  const [selectedNotification, setSelectedNotification] = useState<SentNotification | null>(null)
  const [showDetails, setShowDetails] = useState(false)

  // Filter states
  const [filters, setFilters] = useState<NotificationFilters>({})
  const [searchTerm, setSearchTerm] = useState('')

  // Pagination states
  const [pagination, setPagination] = useState<PaginationInfo>({
    page: 1,
    per_page: 20,
    total: 0,
    total_pages: 0
  })

  // Sort states
  const [sortField, setSortField] = useState<keyof SentNotification>('sent_at')
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('desc')

  const { execute } = useApi()

  useEffect(() => {
    fetchNotifications()
    fetchEvents()
    fetchUsers()
  }, [filters, pagination.page, sortField, sortDirection])

  useEffect(() => {
    const debounceTimer = setTimeout(() => {
      setFilters(prev => ({ ...prev, search: searchTerm || undefined }))
      setPagination(prev => ({ ...prev, page: 1 }))
    }, 500)

    return () => clearTimeout(debounceTimer)
  }, [searchTerm])

  const fetchNotifications = async () => {
    setLoading(true)
    try {
      const queryParams = new URLSearchParams()

      // Add filters
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== undefined && value !== null && value !== '') {
          queryParams.append(key, String(value))
        }
      })

      // Add pagination
      queryParams.append('page', pagination.page.toString())
      queryParams.append('per_page', pagination.per_page.toString())

      // Add sorting
      queryParams.append('sort_by', sortField)
      queryParams.append('sort_direction', sortDirection)

      const response = await execute(`http://localhost:8000/api/schedule-communication/notifications?${queryParams.toString()}`)

      if (response) {
        setNotifications(response.notifications || [])
        setPagination({
          page: response.page || 1,
          per_page: response.per_page || 20,
          total: response.total || 0,
          total_pages: response.total_pages || 0
        })
      }
    } catch (error) {
      console.error('Error fetching notifications:', error)
    } finally {
      setLoading(false)
    }
  }

  const fetchEvents = async () => {
    try {
      const response = await execute('http://localhost:8000/api/events')
      if (response) {
        const events = Array.isArray(response) ? response : []
        setEvents(events.map((event: any) => ({ id: event.id, name: event.name })))
      }
    } catch (error) {
      console.error('Error fetching events:', error)
    }
  }

  const fetchUsers = async () => {
    try {
      const response = await execute('http://localhost:8000/api/users')
      if (response?.users) {
        setUsers(response.users.map((user: any) => ({
          id: user.id,
          name: `${user.first_name} ${user.last_name}`,
          email: user.email
        })))
      }
    } catch (error) {
      console.error('Error fetching users:', error)
    }
  }

  const handleFilterChange = (key: keyof NotificationFilters, value: any) => {
    setFilters(prev => ({
      ...prev,
      [key]: value === '' ? undefined : value
    }))
    setPagination(prev => ({ ...prev, page: 1 }))
  }

  const handleSort = (field: keyof SentNotification) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('desc')
    }
  }

  const handlePageChange = (newPage: number) => {
    setPagination(prev => ({ ...prev, page: newPage }))
  }

  const exportNotifications = async () => {
    try {
      const queryParams = new URLSearchParams()

      Object.entries(filters).forEach(([key, value]) => {
        if (value !== undefined && value !== null && value !== '') {
          queryParams.append(key, String(value))
        }
      })

      queryParams.append('export', 'true')

      const response = await execute(`http://localhost:8000/api/schedule-communication/notifications/export?${queryParams.toString()}`)

      if (response?.download_url) {
        window.open(response.download_url, '_blank')
      }
    } catch (error) {
      console.error('Error exporting notifications:', error)
    }
  }

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getSortIcon = (field: keyof SentNotification) => {
    if (sortField !== field) return <ArrowUpDown className="h-4 w-4 text-gray-400" />
    return sortDirection === 'asc' ?
      <ArrowUpDown className="h-4 w-4 text-blue-600 rotate-180" /> :
      <ArrowUpDown className="h-4 w-4 text-blue-600" />
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="p-2 bg-blue-100 rounded-lg">
            <History className="h-6 w-6 text-blue-600" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Notification Log</h2>
            <p className="text-gray-600">View and manage sent notifications</p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            onClick={exportNotifications}
            className="flex items-center space-x-2"
          >
            <Download className="h-4 w-4" />
            <span>Export</span>
          </Button>
          <Button
            variant="outline"
            onClick={fetchNotifications}
            disabled={loading}
            className="flex items-center space-x-2"
          >
            <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
            <span>Refresh</span>
          </Button>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <Filter className="h-5 w-5" />
            <span>Filters</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Event</label>
              <Select value={filters.event_id || ''} onValueChange={(value) => handleFilterChange('event_id', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="All events" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">All events</SelectItem>
                  {events.map((event) => (
                    <SelectItem key={event.id} value={event.id}>
                      {event.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Recipient</label>
              <Select value={filters.recipient_user_id?.toString() || ''} onValueChange={(value) => handleFilterChange('recipient_user_id', value ? parseInt(value) : undefined)}>
                <SelectTrigger>
                  <SelectValue placeholder="All recipients" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">All recipients</SelectItem>
                  {users.map((user) => (
                    <SelectItem key={user.id} value={user.id.toString()}>
                      {user.name} ({user.email})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Delivery Method</label>
              <Select value={filters.delivery_method || ''} onValueChange={(value) => handleFilterChange('delivery_method', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="All methods" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">All methods</SelectItem>
                  <SelectItem value="email">Email</SelectItem>
                  <SelectItem value="sms">SMS</SelectItem>
                  <SelectItem value="push">Push</SelectItem>
                  <SelectItem value="in_app">In-App</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={filters.status || ''} onValueChange={(value) => handleFilterChange('status', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">All statuses</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="delivered">Delivered</SelectItem>
                  <SelectItem value="failed">Failed</SelectItem>
                  <SelectItem value="bounced">Bounced</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="mt-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">Search</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
              <Input
                placeholder="Search by event name, recipient name, or message content..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Notifications Table */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
          <span className="ml-3 text-gray-500">Loading notifications...</span>
        </div>
      ) : notifications.length === 0 ? (
        <Card>
          <CardContent className="flex items-center justify-center py-12">
            <div className="text-center">
              <History className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">
                No notifications found
              </h3>
              <p className="text-gray-500">
                No notifications match your current filters.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <button
                        onClick={() => handleSort('event_name')}
                        className="flex items-center space-x-1 hover:text-gray-700"
                      >
                        <span>Event</span>
                        {getSortIcon('event_name')}
                      </button>
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <button
                        onClick={() => handleSort('recipient_name')}
                        className="flex items-center space-x-1 hover:text-gray-700"
                      >
                        <span>Recipient</span>
                        {getSortIcon('recipient_name')}
                      </button>
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <button
                        onClick={() => handleSort('delivery_method')}
                        className="flex items-center space-x-1 hover:text-gray-700"
                      >
                        <span>Method</span>
                        {getSortIcon('delivery_method')}
                      </button>
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <button
                        onClick={() => handleSort('status')}
                        className="flex items-center space-x-1 hover:text-gray-700"
                      >
                        <span>Status</span>
                        {getSortIcon('status')}
                      </button>
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <button
                        onClick={() => handleSort('sent_at')}
                        className="flex items-center space-x-1 hover:text-gray-700"
                      >
                        <span>Sent</span>
                        {getSortIcon('sent_at')}
                      </button>
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  <AnimatePresence>
                    {notifications.map((notification) => {
                      const methodConfig = deliveryMethodConfig[notification.delivery_method]
                      const statusInfo = statusConfig[notification.status]
                      const MethodIcon = methodConfig.icon
                      const StatusIcon = statusInfo.icon

                      return (
                        <motion.tr
                          key={notification.id}
                          variants={itemVariants}
                          initial="hidden"
                          animate="visible"
                          exit="hidden"
                          className="hover:bg-gray-50"
                        >
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center">
                              <Calendar className="h-4 w-4 text-gray-400 mr-2" />
                              <div>
                                <div className="text-sm font-medium text-gray-900">{notification.event_name}</div>
                                <div className="text-sm text-gray-500">{notification.template_name || 'Custom Message'}</div>
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div>
                              <div className="text-sm font-medium text-gray-900">{notification.recipient_name}</div>
                              <div className="text-sm text-gray-500">{notification.recipient_email}</div>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center space-x-2">
                              <div className={`p-1 rounded ${methodConfig.bg}`}>
                                <MethodIcon className={`h-4 w-4 ${methodConfig.color}`} />
                              </div>
                              <span className="text-sm font-medium">{methodConfig.label}</span>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center space-x-2">
                              <div className={`p-1 rounded ${statusInfo.bg}`}>
                                <StatusIcon className={`h-4 w-4 ${statusInfo.color}`} />
                              </div>
                              <span className={`text-sm font-medium ${statusInfo.color}`}>{statusInfo.label}</span>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            {formatDate(notification.sent_at)}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => {
                                setSelectedNotification(notification)
                                setShowDetails(true)
                              }}
                              className="flex items-center space-x-1"
                            >
                              <Eye className="h-4 w-4" />
                              <span>View</span>
                            </Button>
                          </td>
                        </motion.tr>
                      )
                    })}
                  </AnimatePresence>
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            {pagination.total_pages > 1 && (
              <div className="px-6 py-4 border-t bg-gray-50">
                <div className="flex items-center justify-between">
                  <div className="text-sm text-gray-700">
                    Showing {((pagination.page - 1) * pagination.per_page) + 1} to {Math.min(pagination.page * pagination.per_page, pagination.total)} of {pagination.total} results
                  </div>
                  <div className="flex items-center space-x-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handlePageChange(pagination.page - 1)}
                      disabled={pagination.page <= 1}
                    >
                      <ChevronLeft className="h-4 w-4" />
                      Previous
                    </Button>
                    <span className="text-sm text-gray-700">
                      Page {pagination.page} of {pagination.total_pages}
                    </span>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handlePageChange(pagination.page + 1)}
                      disabled={pagination.page >= pagination.total_pages}
                    >
                      Next
                      <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Notification Details Modal */}
      <Dialog open={showDetails} onOpenChange={setShowDetails}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Notification Details</DialogTitle>
            <DialogDescription>
              View detailed information about this notification
            </DialogDescription>
          </DialogHeader>

          {selectedNotification && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Event</label>
                  <p className="text-sm text-gray-900">{selectedNotification.event_name}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Recipient</label>
                  <p className="text-sm text-gray-900">
                    {selectedNotification.recipient_name} ({selectedNotification.recipient_email})
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Delivery Method</label>
                  <p className="text-sm text-gray-900">{deliveryMethodConfig[selectedNotification.delivery_method].label}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Status</label>
                  <p className={`text-sm font-medium ${statusConfig[selectedNotification.status].color}`}>
                    {statusConfig[selectedNotification.status].label}
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Sent At</label>
                  <p className="text-sm text-gray-900">{formatDate(selectedNotification.sent_at)}</p>
                </div>
                {selectedNotification.delivered_at && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Delivered At</label>
                    <p className="text-sm text-gray-900">{formatDate(selectedNotification.delivered_at)}</p>
                  </div>
                )}
              </div>

              {selectedNotification.subject && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Subject</label>
                  <div className="p-3 bg-gray-50 rounded-lg border">
                    <p className="text-sm">{selectedNotification.subject}</p>
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Message</label>
                <div className="p-3 bg-gray-50 rounded-lg border">
                  <p className="text-sm whitespace-pre-wrap">{selectedNotification.body}</p>
                </div>
              </div>

              {selectedNotification.error_message && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Error Message</label>
                  <div className="p-3 bg-red-50 rounded-lg border border-red-200">
                    <p className="text-sm text-red-800">{selectedNotification.error_message}</p>
                  </div>
                </div>
              )}
            </div>
          )}

          <div className="flex justify-end">
            <Button variant="outline" onClick={() => setShowDetails(false)}>
              Close
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Download, Calendar, Users, Filter, CheckCircle, AlertCircle,
  CalendarDays, Clock, MapPin, FileText, Settings
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select'
import { useApi } from '../hooks/useApi'
import { ApiEvent } from '../lib/api'

interface CalendarExportButtonProps {
  events?: ApiEvent[]
  selectedEvents?: string[]
  teamId?: number
  variant?: 'button' | 'card'
  className?: string
}

interface ExportOptions {
  format: 'ical' | 'csv' | 'json'
  eventTypes: string[]
  dateRange: 'all' | '30days' | '90days' | '1year' | 'custom'
  startDate?: string
  endDate?: string
  includeDescription: boolean
  includeVenue: boolean
  includeTeams: boolean
  timezone: string
}

interface Team {
  id: number
  name: string
}

const formatConfig = {
  ical: {
    label: 'iCal (.ics)',
    description: 'Compatible with Google Calendar, Outlook, Apple Calendar',
    icon: Calendar,
    mimeType: 'text/calendar'
  },
  csv: {
    label: 'CSV (.csv)',
    description: 'Spreadsheet format for Excel, Google Sheets',
    icon: FileText,
    mimeType: 'text/csv'
  },
  json: {
    label: 'JSON (.json)',
    description: 'Machine-readable format for developers',
    icon: Settings,
    mimeType: 'application/json'
  }
}

const eventTypeOptions = ['Practice', 'Game', 'Meeting', 'Tournament', 'Other']

const dateRangeOptions = {
  all: 'All events',
  '30days': 'Next 30 days',
  '90days': 'Next 90 days',
  '1year': 'Next year',
  custom: 'Custom date range'
}

export default function CalendarExportButton({
  events,
  selectedEvents,
  teamId,
  variant = 'button',
  className = ''
}: CalendarExportButtonProps) {
  const [showExportDialog, setShowExportDialog] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)
  const [teams, setTeams] = useState<Team[]>([])

  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: 'ical',
    eventTypes: eventTypeOptions,
    dateRange: '90days',
    includeDescription: true,
    includeVenue: true,
    includeTeams: true,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
  })

  const { execute } = useApi()

  const handleExportClick = async () => {
    if (variant === 'button') {
      await performExport()
    } else {
      setShowExportDialog(true)
      if (teams.length === 0) {
        await fetchTeams()
      }
    }
  }

  const fetchTeams = async () => {
    try {
      const response = await execute('http://localhost:8000/api/teams')
      if (response?.teams) {
        setTeams(response.teams)
      }
    } catch (error) {
      console.error('Error fetching teams:', error)
    }
  }

  const performExport = async () => {
    setExporting(true)
    setMessage(null)

    try {
      const requestBody: any = {
        format: exportOptions.format,
        event_types: exportOptions.eventTypes,
        date_range: exportOptions.dateRange,
        include_description: exportOptions.includeDescription,
        include_venue: exportOptions.includeVenue,
        include_teams: exportOptions.includeTeams,
        timezone: exportOptions.timezone
      }

      // Add date range if custom
      if (exportOptions.dateRange === 'custom') {
        requestBody.start_date = exportOptions.startDate
        requestBody.end_date = exportOptions.endDate
      }

      // Add team filter if specified
      if (teamId) {
        requestBody.team_id = teamId
      }

      // Add specific events if provided
      if (selectedEvents && selectedEvents.length > 0) {
        requestBody.event_ids = selectedEvents
      }

      const response = await execute('http://localhost:8000/api/schedule-communication/export-calendar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody)
      })

      if (response?.download_url) {
        // Create download link
        const link = document.createElement('a')
        link.href = response.download_url
        link.download = response.filename || `calendar-export.${exportOptions.format}`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)

        setMessage({
          type: 'success',
          text: `Calendar exported successfully as ${formatConfig[exportOptions.format].label}`
        })

        setTimeout(() => {
          setMessage(null)
          setShowExportDialog(false)
        }, 2000)
      } else if (response?.content) {
        // Direct content download
        const blob = new Blob([response.content], {
          type: formatConfig[exportOptions.format].mimeType
        })
        const url = window.URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = response.filename || `calendar-export.${exportOptions.format}`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        window.URL.revokeObjectURL(url)

        setMessage({
          type: 'success',
          text: `Calendar exported successfully as ${formatConfig[exportOptions.format].label}`
        })

        setTimeout(() => {
          setMessage(null)
          setShowExportDialog(false)
        }, 2000)
      }
    } catch (error: any) {
      setMessage({
        type: 'error',
        text: error.message || 'Failed to export calendar'
      })
    } finally {
      setExporting(false)
    }
  }

  const updateEventTypes = (eventType: string, checked: boolean) => {
    setExportOptions(prev => ({
      ...prev,
      eventTypes: checked
        ? [...prev.eventTypes, eventType]
        : prev.eventTypes.filter(type => type !== eventType)
    }))
  }

  const getEventCount = (): number => {
    if (selectedEvents) {
      return selectedEvents.length
    }
    if (events) {
      return events.filter(event => {
        if (teamId && !event.team_ids.includes(teamId)) return false
        if (!exportOptions.eventTypes.includes(event.event_type)) return false
        return true
      }).length
    }
    return 0
  }

  if (variant === 'button') {
    return (
      <Button
        onClick={handleExportClick}
        disabled={exporting}
        className={`flex items-center space-x-2 ${className}`}
      >
        <Download className="h-4 w-4" />
        <span>{exporting ? 'Exporting...' : 'Export Calendar'}</span>
      </Button>
    )
  }

  return (
    <>
      <Card className={`cursor-pointer hover:shadow-md transition-shadow ${className}`} onClick={handleExportClick}>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <div className="p-2 bg-green-100 rounded-lg">
              <Download className="h-5 w-5 text-green-600" />
            </div>
            <span>Export Calendar</span>
          </CardTitle>
          <CardDescription>
            Download events as iCal, CSV, or JSON for use in external calendar applications
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-600">
              {selectedEvents ? `${selectedEvents.length} selected events` : 'All matching events'}
            </div>
            <Button size="sm" className="flex items-center space-x-1">
              <Calendar className="h-4 w-4" />
              <span>Export</span>
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Export Configuration Dialog */}
      <Dialog open={showExportDialog} onOpenChange={setShowExportDialog}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Export Calendar</DialogTitle>
            <DialogDescription>
              Configure your calendar export settings
            </DialogDescription>
          </DialogHeader>

          {/* Message Display */}
          <AnimatePresence>
            {message && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className={`p-4 rounded-lg border ${
                  message.type === 'success'
                    ? 'bg-green-50 border-green-200 text-green-800'
                    : 'bg-red-50 border-red-200 text-red-800'
                }`}
              >
                <div className="flex items-center space-x-2">
                  {message.type === 'success' ? (
                    <CheckCircle className="h-5 w-5" />
                  ) : (
                    <AlertCircle className="h-5 w-5" />
                  )}
                  <span>{message.text}</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="space-y-6">
            {/* Format Selection */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-3">Export Format</label>
              <div className="grid grid-cols-1 gap-3">
                {Object.entries(formatConfig).map(([format, config]) => {
                  const Icon = config.icon
                  return (
                    <label
                      key={format}
                      className={`flex items-center p-3 border rounded-lg cursor-pointer transition-colors ${
                        exportOptions.format === format
                          ? 'border-blue-500 bg-blue-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <input
                        type="radio"
                        name="format"
                        value={format}
                        checked={exportOptions.format === format}
                        onChange={(e) => setExportOptions(prev => ({ ...prev, format: e.target.value as 'ical' | 'csv' | 'json' }))}
                        className="sr-only"
                      />
                      <div className="flex items-center space-x-3 flex-1">
                        <Icon className="h-5 w-5 text-gray-600" />
                        <div>
                          <div className="font-medium text-gray-900">{config.label}</div>
                          <div className="text-sm text-gray-500">{config.description}</div>
                        </div>
                      </div>
                    </label>
                  )
                })}
              </div>
            </div>

            {/* Date Range Selection */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Date Range</label>
              <Select
                value={exportOptions.dateRange}
                onValueChange={(value: 'all' | '30days' | '90days' | '1year' | 'custom') =>
                  setExportOptions(prev => ({ ...prev, dateRange: value }))
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(dateRangeOptions).map(([value, label]) => (
                    <SelectItem key={value} value={value}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {exportOptions.dateRange === 'custom' && (
                <div className="grid grid-cols-2 gap-4 mt-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Start Date</label>
                    <input
                      type="date"
                      value={exportOptions.startDate || ''}
                      onChange={(e) => setExportOptions(prev => ({ ...prev, startDate: e.target.value }))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">End Date</label>
                    <input
                      type="date"
                      value={exportOptions.endDate || ''}
                      onChange={(e) => setExportOptions(prev => ({ ...prev, endDate: e.target.value }))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Event Type Selection */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-3">Event Types</label>
              <div className="grid grid-cols-2 gap-3">
                {eventTypeOptions.map((eventType) => (
                  <label key={eventType} className="flex items-center space-x-2">
                    <input
                      type="checkbox"
                      checked={exportOptions.eventTypes.includes(eventType)}
                      onChange={(e) => updateEventTypes(eventType, e.target.checked)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="text-sm font-medium text-gray-700">{eventType}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Additional Options */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-3">Include Additional Information</label>
              <div className="space-y-3">
                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={exportOptions.includeDescription}
                    onChange={(e) => setExportOptions(prev => ({ ...prev, includeDescription: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <div className="flex items-center space-x-2">
                    <FileText className="h-4 w-4 text-gray-500" />
                    <span className="text-sm font-medium text-gray-700">Event descriptions</span>
                  </div>
                </label>

                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={exportOptions.includeVenue}
                    onChange={(e) => setExportOptions(prev => ({ ...prev, includeVenue: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <div className="flex items-center space-x-2">
                    <MapPin className="h-4 w-4 text-gray-500" />
                    <span className="text-sm font-medium text-gray-700">Venue information</span>
                  </div>
                </label>

                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={exportOptions.includeTeams}
                    onChange={(e) => setExportOptions(prev => ({ ...prev, includeTeams: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <div className="flex items-center space-x-2">
                    <Users className="h-4 w-4 text-gray-500" />
                    <span className="text-sm font-medium text-gray-700">Team assignments</span>
                  </div>
                </label>
              </div>
            </div>

            {/* Timezone */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Timezone</label>
              <Select
                value={exportOptions.timezone}
                onValueChange={(value) => setExportOptions(prev => ({ ...prev, timezone: value }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="UTC">UTC</SelectItem>
                  <SelectItem value="America/New_York">Eastern Time</SelectItem>
                  <SelectItem value="America/Chicago">Central Time</SelectItem>
                  <SelectItem value="America/Denver">Mountain Time</SelectItem>
                  <SelectItem value="America/Los_Angeles">Pacific Time</SelectItem>
                  <SelectItem value={Intl.DateTimeFormat().resolvedOptions().timeZone}>
                    Local Time ({Intl.DateTimeFormat().resolvedOptions().timeZone})
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Summary */}
            <div className="p-4 bg-blue-50 rounded-lg border border-blue-200">
              <h4 className="font-medium text-blue-900 mb-2">Export Summary</h4>
              <div className="text-sm text-blue-800 space-y-1">
                <div className="flex items-center space-x-2">
                  <CalendarDays className="h-4 w-4" />
                  <span>Approximately {getEventCount()} events will be exported</span>
                </div>
                <div className="flex items-center space-x-2">
                  <FileText className="h-4 w-4" />
                  <span>Format: {formatConfig[exportOptions.format].label}</span>
                </div>
                <div className="flex items-center space-x-2">
                  <Clock className="h-4 w-4" />
                  <span>Timezone: {exportOptions.timezone}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="flex space-x-3 pt-4">
            <Button
              variant="outline"
              onClick={() => setShowExportDialog(false)}
              disabled={exporting}
              className="flex-1"
            >
              Cancel
            </Button>
            <Button
              onClick={performExport}
              disabled={exporting || exportOptions.eventTypes.length === 0}
              className="flex-1"
            >
              {exporting ? 'Exporting...' : 'Export Calendar'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}
